class Solution {
    public int maximumSetSize(int[] nums1,int[] nums2){
        Set<Integer> first=new HashSet<>(),second=new HashSet<>();
        for(int value:nums1)first.add(value);
        for(int value:nums2)second.add(value);
        int common=0;
        for(int value:first)if(second.contains(value))common++;
        int half=nums1.length/2,takeFirst=Math.min(half,first.size()-common),takeSecond=Math.min(half,second.size()-common);
        return takeFirst+takeSecond+Math.min(common,2*half-takeFirst-takeSecond);
    }
}

code.kotlin:
class Solution {
    fun maximumSetSize(nums1:IntArray,nums2:IntArray):Int{
        val first=nums1.toHashSet();
        val second=nums2.toHashSet();
        val common=first.count{
            it in second
        };
        val half=nums1.size/2;
        val takeFirst=minOf(half,first.size-common);
        val takeSecond=minOf(half,second.size-common);
        return takeFirst+takeSecond+minOf(common,2*half-takeFirst-takeSecond)
    }
}

