class Solution {
    public:int maximumSetSize(vector<int>& nums1,vector<int>& nums2){
        unordered_set<int> first(nums1.begin(),nums1.end()),second(nums2.begin(),nums2.end());
        int common=0;
        for(int value:first)common+=second.count(value);
        int half=nums1.size()/2,takeFirst=min(half,(int)first.size()-common),takeSecond=min(half,(int)second.size()-common);
        return takeFirst+takeSecond+min(common,2*half-takeFirst-takeSecond);
    }
};
